import {
  type MutableRefObject,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import type { Chart, Plugin } from 'chart.js';

type BleedLines = {
  yZero: number;
  yBottom: number;
};

export function usePosBleedLineSync(
  chartRef: MutableRefObject<Chart<'bar'> | null>,
  dataTestId?: string,
) {
  const shellRef = useRef<HTMLDivElement>(null);
  const bleedHandlerRef = useRef<(chart: Chart<'bar'>) => void>(
    () => undefined,
  );
  const [bleedLines, setBleedLines] = useState<BleedLines | null>(null);

  bleedHandlerRef.current = (chart: Chart<'bar'>) => {
    const shell = shellRef.current;
    if (!shell?.isConnected || !chart.chartArea || chart.height <= 0) {
      return;
    }
    const shellRect = shell.getBoundingClientRect();
    const { canvas } = chart;
    const canvasRect = canvas.getBoundingClientRect();
    const scale = canvasRect.height / chart.height;
    const yZero = chart.scales.y.getPixelForValue(0);
    const yBottom = chart.chartArea.bottom;
    if (!Number.isFinite(yZero) || !Number.isFinite(yBottom)) {
      return;
    }
    const next = {
      yZero: canvasRect.top - shellRect.top + yZero * scale,
      yBottom: canvasRect.top - shellRect.top + yBottom * scale,
    };
    setBleedLines((prev) =>
      prev &&
      Math.abs(prev.yZero - next.yZero) < 0.5 &&
      Math.abs(prev.yBottom - next.yBottom) < 0.5
        ? prev
        : next,
    );
  };

  const bleedSyncPlugin = useMemo<Plugin<'bar'>>(
    () => ({
      id: `posBleedLineSync-${dataTestId ?? 'pos-performance'}`,
      afterDraw(chart) {
        bleedHandlerRef.current(chart);
      },
    }),
    [dataTestId],
  );

  useLayoutEffect(() => {
    const shell = shellRef.current;
    if (!shell) {
      return;
    }
    const sync = () => {
      const ch = chartRef.current;
      if (ch) {
        bleedHandlerRef.current(ch);
      }
    };
    const ro = new ResizeObserver(sync);
    ro.observe(shell);
    sync();
    return () => ro.disconnect();
  }, [chartRef]);

  return { shellRef, bleedLines, bleedSyncPlugin };
}
